import java.util.*;import java.time.*; abstract class Subscription08{LocalDate d;Subscription08(LocalDate d){this.d=d;}abstract int days();LocalDate renewal(){return d.plusDays(days());}} class Basic08 extends Subscription08{Basic08(LocalDate d){super(d);}int days(){return 30;}} class Standard08 extends Subscription08{Standard08(LocalDate d){super(d);}int days(){return 90;}} class Premium08 extends Subscription08{Premium08(LocalDate d){super(d);}int days(){return 365;}} public class Week08Problem05{public static void main(String[]z){Scanner s=new Scanner(System.in);String t=s.next().toUpperCase();LocalDate d=LocalDate.parse(s.next());Subscription08 a=t.equals("BASIC")?new Basic08(d):t.equals("STANDARD")?new Standard08(d):new Premium08(d);System.out.println(a.renewal());}}